<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {ArrowRight,LoaderCircle,LockKeyhole,ChevronDown} from 'lucide-vue-next'
import {api,auth,token,saveManaged} from '../api'
import {endInput,endTimestamp,timelineTime} from '../boarding-schedule'
import {priceValue,priceUnit} from '../card-pricing'
import {retryableSubmission} from '../retryable-submission'
import HumanCheck from './HumanCheck.vue'
import AccountContact from './AccountContact.vue'
import OcrInput from './OcrInput.vue'
const props=defineProps({card:Object});const emit=defineEmits(['saved','publish-team','browse','records'])
const uncertain=ref(false),guestManage=token()
const send=retryableSubmission(options=>api(options.path,options))
const requestedStart=ref(endInput(new Date())),duration=ref(6)
const requestedEnd=computed(()=>{const start=Date.parse(requestedStart.value+'+08:00'),hours=Number(duration.value);return Number.isFinite(start)&&hours>0?new Date(start+hours*3600000).toISOString():''})
const busy=ref(false),contactBusy=ref(false),error=ref(''),human=ref(null),teams=ref([]),teamsLoading=ref(props.card.type==='boss'),errorCode=ref('')
const eligible=t=>Number(t.remaining)>0&&props.card.level>=t.level_min&&props.card.level<=t.level_max&&(props.card.flower!=='active'||t.flower==='active')
const eligibleTeams=computed(()=>teams.value.filter(eligible))
const selectedTeam=computed(()=>teams.value.find(t=>t.id===f.value.offered_team_id))
const f=ref({card_type:props.card.type,card_id:props.card.id,game_id:'',level:null,notes:'',offered_team_id:null,contact:{wechat:'',qr:''},challenge_id:'',answer:'',website:''})
async function loadTeams(){teamsLoading.value=true;error.value='';try{teams.value=(await api('/me')).cards.filter(c=>c.type==='team'&&c.status==='active');if(eligibleTeams.value.length===1)f.value.offered_team_id=eligibleTeams.value[0].id}catch(e){error.value=e.message}finally{teamsLoading.value=false}}
onMounted(()=>{if(props.card.type==='boss')loadTeams()})
watch(()=>f.value.offered_team_id,id=>{const team=teams.value.find(t=>t.id===id);if(team){f.value.game_id=team.game_id;f.value.level=team.level}})
async function submit(){if(busy.value||contactBusy.value)return;if(!uncertain.value&&!f.value.contact.wechat?.trim()&&!f.value.contact.qr){error.value='填写微信号或上传微信二维码，任选一种即可。';return}busy.value=true;error.value='';const manage=auth.user?'':guestManage;try{const result=await send({path:'/applications',method:'POST',data:{...f.value,...(props.card.type==='team'?{requested_start_at:endTimestamp(requestedStart.value),duration_hours:Number(duration.value)}:{})},manage});if(manage)saveManaged('application',result.id,manage,props.card.map_name);emit('saved',{...result,manage,type:'application'})}catch(e){uncertain.value=Boolean(e.uncertain);error.value=e.message;errorCode.value=e.code||'';if(!e.uncertain)human.value?.refresh()}finally{busy.value=false}}
</script>
<template><form class="stack" @submit.prevent="submit"><fieldset class="submission-fields stack" :disabled="busy||uncertain"><div class="selected-card"><small>{{card.type==='team'?'申请加入队伍':'认领老板'}} · {{card.map_name}}</small><h3>{{card.game_id}} <span>Lv.{{card.level}}</span></h3><p>{{card.start_time}} — {{card.end_time<=card.start_time?'次日 ':''}}{{card.end_time}} · {{priceValue(card)}} {{priceUnit(card)}}</p></div><template v-if="card.type==='boss'"><label>选择你发布的队伍<select v-model.number="f.offered_team_id" required><option :value="null" disabled>选择一个招募中的队伍</option><option v-for="t in teams" :key="t.id" :value="t.id" :disabled="!eligible(t)">{{t.map_name}} · {{t.game_id}} · {{eligible(t)?'余 '+t.remaining+' 位':'等级或空位不符合'}}</option></select></label><p v-if="teamsLoading" class="hint">正在查找你的可用队伍…</p><p v-else-if="!teams.length" class="warning">请先发布一支队伍，再来认领老板。</p><p v-else-if="!eligibleTeams.length" class="warning">暂无符合这位老板等级、空位及配置要求的队伍，请调整队伍后再来认领。</p><div v-if="!teamsLoading&&!eligibleTeams.length" class="button-row"><button type="button" class="button primary small" @click="emit('publish-team')">发布队伍并继续认领</button><button type="button" class="button small" @click="loadTeams">重新检查队伍</button></div><p v-if="selectedTeam" class="hint">已使用队伍角色 {{selectedTeam.game_id}} · Lv.{{selectedTeam.level}}，无需重复填写。</p><p class="hint">老板希望 {{card.start_time}} — {{card.end_time<=card.start_time?'次日 ':''}}{{card.end_time}} 挂机。认领后自动带入时段，可在“我的记录”调整。</p></template><template v-if="card.type==='team'"><OcrInput @apply="d=>{if(d.game_id)f.game_id=d.game_id;if(d.level)f.level=d.level}"/><div class="form-grid"><label>游戏 ID<input v-model="f.game_id" required maxlength="40" placeholder="方便对方在游戏中找到你"></label><label>等级<input v-model.number="f.level" type="number" :min="card.level_min" :max="card.level_max" required></label></div><p class="hint">这支队伍接收 Lv.{{card.level_min}}–{{card.level_max}} 的老板。</p></template><template v-if="card.type==='team'"><div class="form-grid request-schedule"><div class="request-start"><div class="schedule-label"><label for="requested-boarding">预计上车时间</label><button type="button" class="time-now" @click="requestedStart=endInput(new Date())">此时</button></div><input id="requested-boarding" type="datetime-local" v-model="requestedStart" required></div><label>挂机时长<select v-model.number="duration" required><option v-for="n in 24" :key="n" :value="n">{{n}} 小时</option></select></label></div><p class="hint">预计离队：{{timelineTime(requestedEnd)}} · 北京时间。时段由打手确认，沟通后可调整。</p></template><AccountContact v-model="f.contact" @validating="contactBusy=$event"/><details class="form-more"><summary>补充留言 <small>选填</small><ChevronDown :size="16"/></summary><label>留言<textarea v-model="f.notes" rows="2" maxlength="400" placeholder="说明你的上线时间或其他需求"></textarea></label></details><HumanCheck ref="human" v-model="f"/><p class="disclaimer">平台不提供支付、担保或纠纷赔付。请在游戏中核对角色身份，先确认时段、费用和规则，谨慎预付；不要提供账号密码或验证码。</p><p class="hint"><LockKeyhole :size="13"/> {{card.type==='boss'?'先到先得。认领成功即可查看老板微信，系统通知老板，无需对方同意；沟通后由你确认上车。':'同意申请后，双方可查看已授权的微信联系方式。'}}</p></fieldset><p v-if="uncertain" class="hint">核对成功后会自动保存记录，无需重新填写。请暂时不要关闭本页。</p><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="['BOSS_CLAIMED','CARD_EXPIRED','CARD_UNAVAILABLE','INVALID_STATE','DUPLICATE_APPLICATION'].includes(errorCode)" class="button-row"><button type="button" class="button" @click="emit(errorCode==='DUPLICATE_APPLICATION'?'records':'browse')">{{errorCode==='DUPLICATE_APPLICATION'?'查看原申请':'返回列表重新选择'}}</button></div><button class="button primary full" :disabled="busy||contactBusy||(card.type==='boss'&&(!selectedTeam||!eligible(selectedTeam)))"><LoaderCircle v-if="busy" :size="17" class="spin"/>{{busy?'提交中…':uncertain?'核对上次提交结果':card.type==='boss'?'立即认领并查看微信':'提交申请'}}<ArrowRight :size="17"/></button></form></template>
